INSERT INTO assessment_questions(questionnaire_version_id, competency_code, position, title, question_text)
VALUES
('00000000-0000-0000-0000-000000000001', 'programming-fundamentals', 1, 'Fundamentos de programación', '¿Qué experiencia tenés utilizando los fundamentos de programación para desarrollar y modificar programas?'),
('00000000-0000-0000-0000-000000000001', 'algorithms', 2, 'Algoritmos y resolución eficiente de problemas', '¿Qué experiencia tenés diseñando o utilizando algoritmos para procesar información y resolver problemas, eligiendo soluciones adecuadas según su funcionamiento y eficiencia?'),
('00000000-0000-0000-0000-000000000001', 'data-structures', 3, 'Estructuras de datos', '¿Qué experiencia tenés seleccionando y utilizando estructuras de datos para organizar y procesar información?'),
('00000000-0000-0000-0000-000000000001', 'object-oriented-programming', 4, 'Programación orientada a objetos', '¿Qué experiencia tenés utilizando programación orientada a objetos para modelar y desarrollar aplicaciones?'),
('00000000-0000-0000-0000-000000000001', 'basic-architecture', 5, 'Principios de diseño y arquitectura básica', '¿Qué experiencia tenés organizando la estructura de una aplicación para facilitar su desarrollo, mantenimiento y evolución?'),
('00000000-0000-0000-0000-000000000001', 'sql-queries', 6, 'Consultas SQL', '¿Qué experiencia tenés utilizando SQL para consultar, relacionar y modificar información en bases de datos relacionales?'),
('00000000-0000-0000-0000-000000000001', 'database-modeling', 7, 'Modelado de bases de datos', '¿Qué experiencia tenés diseñando la estructura de una base de datos relacional a partir de los requisitos de una aplicación?'),
('00000000-0000-0000-0000-000000000001', 'rest-api-consumption', 8, 'Consumo de APIs REST', '¿Qué experiencia tenés integrando aplicaciones con servicios externos mediante APIs REST?'),
('00000000-0000-0000-0000-000000000001', 'rest-api-development', 9, 'Desarrollo de APIs REST', '¿Qué experiencia tenés desarrollando APIs REST para exponer funcionalidades y datos de una aplicación?'),
('00000000-0000-0000-0000-000000000001', 'business-rules', 10, 'Implementación de reglas de negocio', '¿Qué experiencia tenés interpretando requisitos e implementando las reglas que determinan el comportamiento de una aplicación?'),
('00000000-0000-0000-0000-000000000001', 'web-interface-development', 11, 'Desarrollo de interfaces web', '¿Qué experiencia tenés desarrollando y adaptando interfaces web para que los usuarios puedan interactuar con una aplicación?'),
('00000000-0000-0000-0000-000000000001', 'state-management', 12, 'Gestión de estado', '¿Qué experiencia tenés gestionando los datos y cambios de estado que determinan el comportamiento de una interfaz?'),
('00000000-0000-0000-0000-000000000001', 'debugging', 13, 'Depuración y resolución de errores', '¿Qué nivel de capacidad tenés para investigar y corregir errores en el código de una aplicación?'),
('00000000-0000-0000-0000-000000000001', 'git-version-control', 14, 'Git y control de versiones', '¿Qué experiencia tenés utilizando Git para gestionar cambios y colaborar en proyectos de software?'),
('00000000-0000-0000-0000-000000000001', 'integration-collaboration', 15, 'Integración y colaboración en proyectos', '¿Qué nivel de capacidad tenés para integrar tu trabajo con el de otras personas en un proyecto tecnológico?'),
('00000000-0000-0000-0000-000000000001', 'docker-containers', 16, 'Docker y contenedores', '¿Qué experiencia tenés utilizando contenedores para ejecutar y configurar aplicaciones y sus servicios?'),
('00000000-0000-0000-0000-000000000001', 'testing-fundamentals', 17, 'Fundamentos y tipos de testing', '¿Qué nivel de conocimiento y aplicación tenés sobre los fundamentos y tipos de pruebas de software?'),
('00000000-0000-0000-0000-000000000001', 'test-case-design', 18, 'Diseño de casos de prueba', '¿Qué experiencia tenés diseñando casos de prueba para verificar que una aplicación cumpla con sus requisitos?'),
('00000000-0000-0000-0000-000000000001', 'test-execution-documentation', 19, 'Ejecución y documentación de pruebas', '¿Qué experiencia tenés ejecutando pruebas y documentando sus resultados para verificar el funcionamiento de una aplicación?'),
('00000000-0000-0000-0000-000000000001', 'defect-management', 20, 'Gestión de defectos', '¿Qué experiencia tenés identificando, reportando y realizando el seguimiento de defectos encontrados durante las pruebas de software?'),
('00000000-0000-0000-0000-000000000001', 'api-testing', 21, 'Pruebas de APIs', '¿Qué experiencia tenés probando APIs para verificar que sus endpoints funcionen correctamente?'),
('00000000-0000-0000-0000-000000000001', 'exploratory-data-analysis', 22, 'Análisis exploratorio de datos', '¿Qué nivel de capacidad tenés para explorar conjuntos de datos e identificar información relevante?'),
('00000000-0000-0000-0000-000000000001', 'data-cleaning-preparation', 23, 'Limpieza y preparación de datos', '¿Qué nivel de capacidad tenés para identificar y corregir problemas en conjuntos de datos?'),
('00000000-0000-0000-0000-000000000001', 'data-visualization-dashboards', 24, 'Visualización de datos y dashboards', '¿Qué nivel de capacidad tenés para representar información mediante gráficos y dashboards?'),
('00000000-0000-0000-0000-000000000001', 'applied-statistics', 25, 'Estadística aplicada', '¿Qué nivel de conocimiento y aplicación tenés sobre conceptos estadísticos para analizar e interpretar datos?'),
('00000000-0000-0000-0000-000000000001', 'business-metrics-interpretation', 26, 'Interpretación de métricas de negocio', '¿Qué nivel de capacidad tenés para interpretar indicadores y relacionarlos con objetivos de negocio?'),
('00000000-0000-0000-0000-000000000001', 'cloud-computing-fundamentals', 27, 'Fundamentos de Cloud Computing', '¿Qué nivel de conocimiento y experiencia tenés utilizando servicios de computación en la nube, como AWS, Azure o Google Cloud?'),
('00000000-0000-0000-0000-000000000001', 'linux-operating-systems', 28, 'Linux y sistemas operativos', '¿Qué nivel de conocimiento y aplicación tenés sobre Linux y la administración básica de sistemas operativos?'),
('00000000-0000-0000-0000-000000000001', 'networking-fundamentals', 29, 'Fundamentos de redes', '¿Qué nivel de conocimiento y aplicación tenés sobre redes y comunicación entre sistemas?'),
('00000000-0000-0000-0000-000000000001', 'scripting-automation', 30, 'Automatización de tareas mediante scripts (Bash, PowerShell o Python)', '¿Qué nivel de experiencia tenés creando pequeños programas o scripts para automatizar tareas repetitivas?'),
('00000000-0000-0000-0000-000000000001', 'infrastructure-monitoring-diagnostics', 31, 'Monitoreo y diagnóstico de infraestructura', '¿Qué nivel de capacidad tenés para supervisar el funcionamiento de sistemas e identificar problemas de infraestructura?');
INSERT INTO assessment_answer_options(questionnaire_version_id, competency_code, level, description)
VALUES
('00000000-0000-0000-0000-000000000001', 'programming-fundamentals', 0, 'No conozco conceptos como variables, condiciones, ciclos o funciones.'),
('00000000-0000-0000-0000-000000000001', 'programming-fundamentals', 1, 'Comprendo para qué sirven estos elementos y puedo reconocer cómo se utilizan en programas sencillos.'),
('00000000-0000-0000-0000-000000000001', 'programming-fundamentals', 2, 'Puedo escribir o modificar programas sencillos utilizando variables, condiciones, ciclos y funciones, comprendiendo su funcionamiento.'),
('00000000-0000-0000-0000-000000000001', 'programming-fundamentals', 3, 'Tengo experiencia desarrollando programas para resolver problemas habituales, organizando la lógica en funciones e identificando y corrigiendo errores.'),
('00000000-0000-0000-0000-000000000001', 'programming-fundamentals', 4, 'Puedo analizar diferentes formas de resolver un problema, identificar errores lógicos, mejorar la organización del código y justificar las decisiones tomadas.'),
('00000000-0000-0000-0000-000000000001', 'algorithms', 0, 'No conozco qué es un algoritmo ni cómo se utiliza para resolver problemas.'),
('00000000-0000-0000-0000-000000000001', 'algorithms', 1, 'Comprendo qué es un algoritmo y cómo se utiliza para realizar tareas como buscar, recorrer u ordenar información.'),
('00000000-0000-0000-0000-000000000001', 'algorithms', 2, 'Puedo implementar o adaptar algoritmos sencillos para procesar información y resolver problemas, comprendiendo cómo funcionan.'),
('00000000-0000-0000-0000-000000000001', 'algorithms', 3, 'Puedo seleccionar diferentes soluciones algorítmicas según el problema, comprobar sus resultados y reconocer diferencias de eficiencia.'),
('00000000-0000-0000-0000-000000000001', 'algorithms', 4, 'Puedo comparar algoritmos, analizar su complejidad y optimizar soluciones según el volumen de datos, los recursos disponibles y los requisitos.'),
('00000000-0000-0000-0000-000000000001', 'data-structures', 0, 'No conozco las estructuras de datos.'),
('00000000-0000-0000-0000-000000000001', 'data-structures', 1, 'Comprendo para qué sirven estructuras como arreglos, listas, conjuntos, pilas, colas o mapas.'),
('00000000-0000-0000-0000-000000000001', 'data-structures', 2, 'Puedo utilizar estructuras de datos habituales, como listas, conjuntos y mapas, para almacenar, buscar y procesar información, comprendiendo sus diferencias básicas.'),
('00000000-0000-0000-0000-000000000001', 'data-structures', 3, 'Puedo seleccionar y utilizar diferentes estructuras de datos según las necesidades de una aplicación, comprendiendo cómo permiten almacenar, buscar y modificar información.'),
('00000000-0000-0000-0000-000000000001', 'data-structures', 4, 'Puedo comparar estructuras de datos, identificar sus ventajas y limitaciones y justificar cuál resulta más adecuada según las operaciones y el rendimiento esperado.'),
('00000000-0000-0000-0000-000000000001', 'object-oriented-programming', 0, 'No conozco la programación orientada a objetos.'),
('00000000-0000-0000-0000-000000000001', 'object-oriented-programming', 1, 'Comprendo conceptos como clases, objetos, atributos y métodos, y para qué se utilizan.'),
('00000000-0000-0000-0000-000000000001', 'object-oriented-programming', 2, 'Puedo crear clases y objetos sencillos, aplicar encapsulamiento y establecer relaciones básicas entre ellos.'),
('00000000-0000-0000-0000-000000000001', 'object-oriented-programming', 3, 'Puedo modelar y desarrollar aplicaciones utilizando encapsulamiento, interfaces, herencia o polimorfismo cuando corresponde, comprendiendo el propósito de cada decisión.'),
('00000000-0000-0000-0000-000000000001', 'object-oriented-programming', 4, 'Puedo evaluar diferentes diseños orientados a objetos, identificar problemas de responsabilidad, cohesión o acoplamiento y mejorar el modelo utilizando relaciones y mecanismos adecuados.'),
('00000000-0000-0000-0000-000000000001', 'basic-architecture', 0, 'No conozco principios para organizar o diseñar software.'),
('00000000-0000-0000-0000-000000000001', 'basic-architecture', 1, 'Comprendo conceptos como modularidad, separación de responsabilidades y organización por capas.'),
('00000000-0000-0000-0000-000000000001', 'basic-architecture', 2, 'Puedo organizar una aplicación sencilla en clases, funciones o módulos, diferenciando sus responsabilidades principales.'),
('00000000-0000-0000-0000-000000000001', 'basic-architecture', 3, 'Puedo organizar una aplicación en componentes o capas con responsabilidades definidas, comprendiendo por qué resulta conveniente esa estructura.'),
('00000000-0000-0000-0000-000000000001', 'basic-architecture', 4, 'Puedo evaluar alternativas de diseño, identificar problemas de acoplamiento o mantenimiento, justificar decisiones arquitectónicas básicas y mejorar la estructura de una aplicación.'),
('00000000-0000-0000-0000-000000000001', 'sql-queries', 0, 'No conozco SQL ni para qué se utiliza.'),
('00000000-0000-0000-0000-000000000001', 'sql-queries', 1, 'Comprendo qué es SQL y cómo permite consultar y modificar información almacenada en tablas.'),
('00000000-0000-0000-0000-000000000001', 'sql-queries', 2, 'Puedo realizar consultas sencillas para obtener, filtrar o modificar información y comprender los resultados obtenidos.'),
('00000000-0000-0000-0000-000000000001', 'sql-queries', 3, 'Tengo experiencia utilizando SQL para resolver necesidades de una aplicación, relacionar información de distintas tablas y verificar que las consultas produzcan los resultados esperados.'),
('00000000-0000-0000-0000-000000000001', 'sql-queries', 4, 'Puedo evaluar diferentes formas de resolver una consulta, identificar errores o problemas de rendimiento y mejorar las soluciones según las necesidades de la aplicación.'),
('00000000-0000-0000-0000-000000000001', 'database-modeling', 0, 'No conozco cómo se diseña una base de datos.'),
('00000000-0000-0000-0000-000000000001', 'database-modeling', 1, 'Comprendo qué son tablas, columnas, claves primarias y relaciones entre entidades.'),
('00000000-0000-0000-0000-000000000001', 'database-modeling', 2, 'Puedo diseñar tablas y relaciones sencillas, identificando entidades, atributos y claves.'),
('00000000-0000-0000-0000-000000000001', 'database-modeling', 3, 'Puedo diseñar un modelo relacional que represente las entidades, relaciones y restricciones de una aplicación, utilizando claves primarias y foráneas adecuadamente.'),
('00000000-0000-0000-0000-000000000001', 'database-modeling', 4, 'Puedo evaluar diferentes alternativas de modelado, identificar problemas de redundancia o integridad, aplicar normalización cuando corresponde y justificar decisiones según los requisitos.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-consumption', 0, 'No conozco qué es una API.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-consumption', 1, 'Comprendo qué es una API REST y cómo permite intercambiar información entre aplicaciones mediante HTTP.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-consumption', 2, 'Puedo realizar solicitudes a una API existente, enviar parámetros sencillos y utilizar las respuestas obtenidas.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-consumption', 3, 'Puedo integrar APIs en una aplicación, enviar información, procesar respuestas y manejar errores habituales.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-consumption', 4, 'Puedo evaluar diferentes alternativas de integración, gestionar autenticación, paginación y fallos de comunicación, y diseñar soluciones robustas según las necesidades de la aplicación.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-development', 0, 'No conozco cómo se desarrolla una API.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-development', 1, 'Comprendo qué son endpoints, métodos HTTP y respuestas JSON, y para qué se utilizan.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-development', 2, 'Puedo desarrollar endpoints sencillos para consultar o modificar información y comprender cómo se procesan las solicitudes.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-development', 3, 'Tengo experiencia desarrollando APIs REST con operaciones de consulta y modificación de datos, validaciones y respuestas HTTP adecuadas.'),
('00000000-0000-0000-0000-000000000001', 'rest-api-development', 4, 'Puedo diseñar APIs con contratos claros, organizar responsabilidades, gestionar errores consistentemente y justificar decisiones para facilitar su integración y mantenimiento.'),
('00000000-0000-0000-0000-000000000001', 'business-rules', 0, 'No conozco qué son las reglas de negocio.'),
('00000000-0000-0000-0000-000000000001', 'business-rules', 1, 'Comprendo que las aplicaciones deben cumplir condiciones y restricciones definidas por sus requisitos.'),
('00000000-0000-0000-0000-000000000001', 'business-rules', 2, 'Puedo implementar reglas sencillas, como validaciones o cálculos, y comprender cómo afectan al comportamiento de una aplicación.'),
('00000000-0000-0000-0000-000000000001', 'business-rules', 3, 'Puedo interpretar requisitos e implementar reglas que involucran diferentes condiciones, entidades y operaciones, comprobando que el comportamiento sea correcto.'),
('00000000-0000-0000-0000-000000000001', 'business-rules', 4, 'Puedo analizar reglas de mayor complejidad, identificar inconsistencias o casos límite y organizar la lógica para mantener la coherencia de los datos y facilitar cambios futuros.'),
('00000000-0000-0000-0000-000000000001', 'web-interface-development', 0, 'No conozco cómo se desarrolla una interfaz web.'),
('00000000-0000-0000-0000-000000000001', 'web-interface-development', 1, 'Comprendo para qué sirven HTML, CSS y JavaScript, y cómo se relacionan para construir interfaces.'),
('00000000-0000-0000-0000-000000000001', 'web-interface-development', 2, 'Puedo crear o modificar interfaces sencillas con elementos visuales e interacciones básicas, comprendiendo su funcionamiento.'),
('00000000-0000-0000-0000-000000000001', 'web-interface-development', 3, 'Tengo experiencia desarrollando y adaptando interfaces con formularios, componentes reutilizables e integración con servicios, verificando su funcionamiento en diferentes tamaños de pantalla.'),
('00000000-0000-0000-0000-000000000001', 'web-interface-development', 4, 'Puedo evaluar la organización y calidad de una interfaz, identificar problemas de accesibilidad, interacción, adaptación a dispositivos o mantenimiento y mejorar su estructura según los requisitos.'),
('00000000-0000-0000-0000-000000000001', 'state-management', 0, 'No conozco qué significa gestionar el estado de una aplicación.'),
('00000000-0000-0000-0000-000000000001', 'state-management', 1, 'Comprendo que una interfaz puede cambiar según los datos y las acciones del usuario.'),
('00000000-0000-0000-0000-000000000001', 'state-management', 2, 'Puedo implementar estados sencillos, como actualizar formularios o mostrar y ocultar elementos, comprendiendo cómo afectan a la interfaz.'),
('00000000-0000-0000-0000-000000000001', 'state-management', 3, 'Puedo gestionar el estado de componentes, formularios y datos obtenidos de APIs, manteniendo la interfaz sincronizada con la información.'),
('00000000-0000-0000-0000-000000000001', 'state-management', 4, 'Puedo evaluar distintas estrategias de gestión de estado, organizar flujos de datos compartidos, identificar inconsistencias y mejorar el comportamiento o rendimiento de la aplicación.'),
('00000000-0000-0000-0000-000000000001', 'debugging', 0, 'No sé cómo investigar errores de programación.'),
('00000000-0000-0000-0000-000000000001', 'debugging', 1, 'Puedo reconocer mensajes de error, pero necesito ayuda para comprenderlos.'),
('00000000-0000-0000-0000-000000000001', 'debugging', 2, 'Puedo interpretar errores sencillos y realizar correcciones con orientación.'),
('00000000-0000-0000-0000-000000000001', 'debugging', 3, 'Puedo reproducir errores, investigar sus causas y corregir problemas habituales, verificando los resultados.'),
('00000000-0000-0000-0000-000000000001', 'debugging', 4, 'Puedo investigar errores complejos, utilizar herramientas de depuración y comprobar que las correcciones no generan nuevos problemas.'),
('00000000-0000-0000-0000-000000000001', 'git-version-control', 0, 'No conozco Git ni los sistemas de control de versiones.'),
('00000000-0000-0000-0000-000000000001', 'git-version-control', 1, 'Comprendo para qué sirve Git y conceptos como repositorios, commits y ramas.'),
('00000000-0000-0000-0000-000000000001', 'git-version-control', 2, 'Puedo registrar cambios, trabajar con repositorios y realizar operaciones básicas de control de versiones.'),
('00000000-0000-0000-0000-000000000001', 'git-version-control', 3, 'Puedo gestionar ramas, commits, merges y conflictos habituales durante el desarrollo de un proyecto.'),
('00000000-0000-0000-0000-000000000001', 'git-version-control', 4, 'Puedo seleccionar estrategias de trabajo con ramas, mantener un historial claro, resolver conflictos más complejos y recuperar cambios cuando aparecen problemas.'),
('00000000-0000-0000-0000-000000000001', 'integration-collaboration', 0, 'No tengo conocimientos ni experiencia sobre trabajo colaborativo en proyectos.'),
('00000000-0000-0000-0000-000000000001', 'integration-collaboration', 1, 'Participé de manera limitada en un proyecto grupal, realizando tareas sencillas con orientación de otros integrantes.'),
('00000000-0000-0000-0000-000000000001', 'integration-collaboration', 2, 'Tengo experiencia trabajando en equipo sobre tareas asignadas, comunicando avances y siguiendo acuerdos del equipo.'),
('00000000-0000-0000-0000-000000000001', 'integration-collaboration', 3, 'Tengo experiencia trabajando en proyectos grupales, integrando componentes desarrollados por distintos integrantes, coordinando dependencias y resolviendo problemas habituales en conjunto.'),
('00000000-0000-0000-0000-000000000001', 'integration-collaboration', 4, 'Tengo experiencia práctica colaborando activamente en integraciones, detectando incompatibilidades, resolviendo problemas entre componentes y proponiendo mejoras para facilitar el trabajo conjunto.'),
('00000000-0000-0000-0000-000000000001', 'docker-containers', 0, 'No conozco Docker ni el concepto de contenedores.'),
('00000000-0000-0000-0000-000000000001', 'docker-containers', 1, 'Comprendo para qué sirven los contenedores y cómo permiten ejecutar aplicaciones en entornos configurados.'),
('00000000-0000-0000-0000-000000000001', 'docker-containers', 2, 'Puedo ejecutar contenedores existentes y realizar configuraciones sencillas para utilizar aplicaciones o servicios.'),
('00000000-0000-0000-0000-000000000001', 'docker-containers', 3, 'Tengo experiencia configurando y utilizando contenedores en proyectos, creando imágenes con Dockerfile y trabajando con Docker Compose.'),
('00000000-0000-0000-0000-000000000001', 'docker-containers', 4, 'Puedo resolver problemas de configuración, conectividad o ejecución de contenedores y optimizar su uso de forma autónoma.'),
('00000000-0000-0000-0000-000000000001', 'testing-fundamentals', 0, 'No conozco qué es el testing de software.'),
('00000000-0000-0000-0000-000000000001', 'testing-fundamentals', 1, 'Comprendo para qué sirven las pruebas de software y por qué son importantes para detectar errores.'),
('00000000-0000-0000-0000-000000000001', 'testing-fundamentals', 2, 'Puedo reconocer diferentes tipos de pruebas, como funcionales, de integración o regresión, y comprender cuándo pueden utilizarse.'),
('00000000-0000-0000-0000-000000000001', 'testing-fundamentals', 3, 'Tengo experiencia aplicando diferentes tipos de pruebas según las funcionalidades y necesidades de una aplicación.'),
('00000000-0000-0000-0000-000000000001', 'testing-fundamentals', 4, 'Puedo seleccionar y justificar los tipos de pruebas más adecuados según los requisitos, riesgos y características del sistema.'),
('00000000-0000-0000-0000-000000000001', 'test-case-design', 0, 'No conozco qué es un caso de prueba ni cómo se diseña.'),
('00000000-0000-0000-0000-000000000001', 'test-case-design', 1, 'Comprendo qué es un caso de prueba y cómo se utiliza para verificar el funcionamiento de una aplicación.'),
('00000000-0000-0000-0000-000000000001', 'test-case-design', 2, 'Puedo diseñar casos de prueba sencillos a partir de requisitos o funcionalidades, identificando las acciones a realizar y los resultados esperados.'),
('00000000-0000-0000-0000-000000000001', 'test-case-design', 3, 'Tengo experiencia diseñando casos de prueba para distintas funcionalidades, contemplando escenarios habituales, errores posibles y casos límite.'),
('00000000-0000-0000-0000-000000000001', 'test-case-design', 4, 'Tengo experiencia diseñando conjuntos de casos de prueba, identificando escenarios no contemplados, priorizando pruebas según los riesgos y mejorando su cobertura.'),
('00000000-0000-0000-0000-000000000001', 'test-execution-documentation', 0, 'No conozco cómo se ejecutan ni documentan pruebas de software.'),
('00000000-0000-0000-0000-000000000001', 'test-execution-documentation', 1, 'Comprendo cómo se ejecuta una prueba y por qué es importante registrar sus resultados.'),
('00000000-0000-0000-0000-000000000001', 'test-execution-documentation', 2, 'Puedo ejecutar pruebas sencillas siguiendo casos definidos y registrar si los resultados coinciden con los esperados.'),
('00000000-0000-0000-0000-000000000001', 'test-execution-documentation', 3, 'Tengo experiencia ejecutando pruebas sobre distintas funcionalidades, documentando resultados, identificando comportamientos incorrectos y verificando correcciones.'),
('00000000-0000-0000-0000-000000000001', 'test-execution-documentation', 4, 'Tengo experiencia organizando y ejecutando conjuntos de pruebas, manteniendo registros claros, realizando pruebas de regresión y proponiendo mejoras al proceso de validación.'),
('00000000-0000-0000-0000-000000000001', 'defect-management', 0, 'No conozco cómo se identifican ni reportan defectos de software.'),
('00000000-0000-0000-0000-000000000001', 'defect-management', 1, 'Comprendo qué es un defecto y por qué es importante comunicarlo y documentarlo.'),
('00000000-0000-0000-0000-000000000001', 'defect-management', 2, 'Puedo identificar y reportar defectos sencillos, describiendo el problema, los pasos para reproducirlo y el resultado esperado.'),
('00000000-0000-0000-0000-000000000001', 'defect-management', 3, 'Tengo experiencia registrando defectos con información suficiente para reproducirlos, realizando su seguimiento y verificando que las correcciones resuelvan los problemas detectados.'),
('00000000-0000-0000-0000-000000000001', 'defect-management', 4, 'Tengo experiencia gestionando defectos de diferentes características, evaluando su impacto, colaborando con desarrolladores para facilitar su resolución y verificando que las correcciones no introduzcan nuevos problemas.'),
('00000000-0000-0000-0000-000000000001', 'api-testing', 0, 'No conozco cómo se prueba una API.'),
('00000000-0000-0000-0000-000000000001', 'api-testing', 1, 'Comprendo qué es una API y cómo se pueden verificar sus solicitudes y respuestas.'),
('00000000-0000-0000-0000-000000000001', 'api-testing', 2, 'Puedo realizar solicitudes sencillas a una API, utilizando herramientas como Postman, e interpretar las respuestas obtenidas.'),
('00000000-0000-0000-0000-000000000001', 'api-testing', 3, 'Tengo experiencia probando endpoints de APIs, verificando métodos HTTP, códigos de respuesta, datos devueltos y comportamientos ante entradas válidas e inválidas.'),
('00000000-0000-0000-0000-000000000001', 'api-testing', 4, 'Tengo experiencia diseñando y ejecutando pruebas de APIs que contemplan autenticación, validaciones, errores y distintos escenarios de integración, identificando problemas y proponiendo mejoras en su funcionamiento.'),
('00000000-0000-0000-0000-000000000001', 'exploratory-data-analysis', 0, 'No conozco cómo se realiza un análisis exploratorio de datos.'),
('00000000-0000-0000-0000-000000000001', 'exploratory-data-analysis', 1, 'Comprendo para qué sirve explorar datos y cómo permite identificar características, patrones o tendencias.'),
('00000000-0000-0000-0000-000000000001', 'exploratory-data-analysis', 2, 'Puedo explorar conjuntos de datos sencillos, utilizando filtros, agrupaciones y estadísticas descriptivas para obtener información básica.'),
('00000000-0000-0000-0000-000000000001', 'exploratory-data-analysis', 3, 'Tengo experiencia realizando análisis exploratorios sobre conjuntos de datos, identificando patrones, tendencias, valores atípicos y relaciones relevantes.'),
('00000000-0000-0000-0000-000000000001', 'exploratory-data-analysis', 4, 'Tengo experiencia analizando conjuntos de datos de mayor complejidad, seleccionando técnicas de exploración adecuadas, contrastando hallazgos y justificando las conclusiones obtenidas.'),
('00000000-0000-0000-0000-000000000001', 'data-cleaning-preparation', 0, 'No conozco cómo se limpian o preparan conjuntos de datos.'),
('00000000-0000-0000-0000-000000000001', 'data-cleaning-preparation', 1, 'Comprendo que los datos pueden contener errores, valores faltantes, duplicados o formatos inconsistentes que afectan su análisis.'),
('00000000-0000-0000-0000-000000000001', 'data-cleaning-preparation', 2, 'Puedo identificar y corregir problemas sencillos, como registros duplicados, valores faltantes o formatos incorrectos, utilizando herramientas de análisis de datos.'),
('00000000-0000-0000-0000-000000000001', 'data-cleaning-preparation', 3, 'Tengo experiencia limpiando y preparando conjuntos de datos, identificando inconsistencias, aplicando transformaciones y verificando que la información sea adecuada para su análisis.'),
('00000000-0000-0000-0000-000000000001', 'data-cleaning-preparation', 4, 'Tengo experiencia preparando conjuntos de datos de mayor complejidad, evaluando distintas estrategias de limpieza, identificando problemas de calidad y justificando las transformaciones realizadas.'),
('00000000-0000-0000-0000-000000000001', 'data-visualization-dashboards', 0, 'No conozco herramientas ni técnicas de visualización de datos.'),
('00000000-0000-0000-0000-000000000001', 'data-visualization-dashboards', 1, 'Comprendo para qué sirven los gráficos y dashboards y cómo permiten presentar información.'),
('00000000-0000-0000-0000-000000000001', 'data-visualization-dashboards', 2, 'Puedo crear gráficos sencillos a partir de conjuntos de datos y comprender qué información representan.'),
('00000000-0000-0000-0000-000000000001', 'data-visualization-dashboards', 3, 'Tengo experiencia creando visualizaciones y dashboards para presentar indicadores, comparar resultados e identificar tendencias.'),
('00000000-0000-0000-0000-000000000001', 'data-visualization-dashboards', 4, 'Puedo seleccionar visualizaciones adecuadas según los datos y objetivos, organizar dashboards e identificar y corregir problemas que dificultan la interpretación de la información.'),
('00000000-0000-0000-0000-000000000001', 'applied-statistics', 0, 'No conozco conceptos básicos de estadística.'),
('00000000-0000-0000-0000-000000000001', 'applied-statistics', 1, 'Comprendo conceptos como promedio, mediana, porcentajes y variabilidad.'),
('00000000-0000-0000-0000-000000000001', 'applied-statistics', 2, 'Puedo aplicar medidas estadísticas sencillas para resumir conjuntos de datos e interpretar sus resultados.'),
('00000000-0000-0000-0000-000000000001', 'applied-statistics', 3, 'Tengo experiencia utilizando técnicas estadísticas descriptivas para analizar datos, comparar resultados e identificar tendencias o diferencias relevantes.'),
('00000000-0000-0000-0000-000000000001', 'applied-statistics', 4, 'Puedo seleccionar métodos estadísticos adecuados, interpretar sus resultados, reconocer limitaciones y evitar conclusiones incorrectas a partir de los datos.'),
('00000000-0000-0000-0000-000000000001', 'business-metrics-interpretation', 0, 'No conozco qué son las métricas o indicadores de negocio.'),
('00000000-0000-0000-0000-000000000001', 'business-metrics-interpretation', 1, 'Comprendo qué son los indicadores de negocio y cómo permiten evaluar resultados en relación con determinados objetivos.'),
('00000000-0000-0000-0000-000000000001', 'business-metrics-interpretation', 2, 'Puedo interpretar indicadores sencillos, identificar variaciones y explicar qué representan sus resultados.'),
('00000000-0000-0000-0000-000000000001', 'business-metrics-interpretation', 3, 'Tengo experiencia analizando métricas de negocio, relacionándolas con objetivos, identificando tendencias y comunicando conclusiones basadas en los datos.'),
('00000000-0000-0000-0000-000000000001', 'business-metrics-interpretation', 4, 'Tengo experiencia evaluando diferentes indicadores, identificando relaciones y posibles causas de variaciones, contrastando interpretaciones y presentando conclusiones fundamentadas que contribuyan a la toma de decisiones.'),
('00000000-0000-0000-0000-000000000001', 'cloud-computing-fundamentals', 0, 'No conozco qué es la computación en la nube.'),
('00000000-0000-0000-0000-000000000001', 'cloud-computing-fundamentals', 1, 'Comprendo qué es cloud computing y para qué se utilizan sus principales tipos de servicios.'),
('00000000-0000-0000-0000-000000000001', 'cloud-computing-fundamentals', 2, 'Conozco los servicios básicos de una plataforma cloud y puedo realizar configuraciones o tareas sencillas con orientación.'),
('00000000-0000-0000-0000-000000000001', 'cloud-computing-fundamentals', 3, 'Tengo experiencia utilizando y configurando servicios cloud para desplegar aplicaciones, almacenar información o administrar recursos básicos.'),
('00000000-0000-0000-0000-000000000001', 'cloud-computing-fundamentals', 4, 'Tengo experiencia utilizando diferentes servicios cloud, configurando recursos de manera autónoma, resolviendo problemas habituales y tomando decisiones básicas de seguridad, disponibilidad y costos.'),
('00000000-0000-0000-0000-000000000001', 'linux-operating-systems', 0, 'No conozco Linux ni conceptos básicos de administración de sistemas operativos.'),
('00000000-0000-0000-0000-000000000001', 'linux-operating-systems', 1, 'Reconozco conceptos como archivos, directorios, usuarios, permisos y procesos.'),
('00000000-0000-0000-0000-000000000001', 'linux-operating-systems', 2, 'Puedo utilizar comandos básicos para navegar por directorios, gestionar archivos y consultar información del sistema.'),
('00000000-0000-0000-0000-000000000001', 'linux-operating-systems', 3, 'Tengo experiencia utilizando Linux para administrar archivos, permisos, procesos y servicios, y realizar configuraciones habituales.'),
('00000000-0000-0000-0000-000000000001', 'linux-operating-systems', 4, 'Tengo experiencia administrando entornos Linux, diagnosticando problemas de permisos, procesos o servicios y resolviendo incidentes habituales del sistema.'),
('00000000-0000-0000-0000-000000000001', 'networking-fundamentals', 0, 'No conozco los fundamentos de redes.'),
('00000000-0000-0000-0000-000000000001', 'networking-fundamentals', 1, 'Reconozco conceptos básicos como direcciones IP, puertos y protocolos de comunicación.'),
('00000000-0000-0000-0000-000000000001', 'networking-fundamentals', 2, 'Comprendo cómo se comunican los sistemas a través de una red y puedo interpretar situaciones sencillas de conectividad.'),
('00000000-0000-0000-0000-000000000001', 'networking-fundamentals', 3, 'Tengo experiencia utilizando herramientas de red para verificar conexiones, realizar pruebas de comunicación e identificar problemas habituales.'),
('00000000-0000-0000-0000-000000000001', 'networking-fundamentals', 4, 'Tengo experiencia configurando conexiones de red, interpretando diagnósticos y resolviendo problemas habituales de comunicación entre sistemas.'),
('00000000-0000-0000-0000-000000000001', 'scripting-automation', 0, 'No sé qué es un script ni cómo se utiliza.'),
('00000000-0000-0000-0000-000000000001', 'scripting-automation', 1, 'Entiendo qué es un script y para qué sirve, pero todavía no sé crear uno.'),
('00000000-0000-0000-0000-000000000001', 'scripting-automation', 2, 'Puedo ejecutar y modificar scripts sencillos para automatizar tareas básicas.'),
('00000000-0000-0000-0000-000000000001', 'scripting-automation', 3, 'Puedo crear scripts para automatizar tareas concretas, como procesar archivos, ejecutar comandos o realizar verificaciones.'),
('00000000-0000-0000-0000-000000000001', 'scripting-automation', 4, 'Puedo desarrollar, depurar y mejorar scripts de forma autónoma, incluyendo manejo de errores y situaciones imprevistas.'),
('00000000-0000-0000-0000-000000000001', 'infrastructure-monitoring-diagnostics', 0, 'No conozco herramientas ni conceptos de monitoreo de sistemas.'),
('00000000-0000-0000-0000-000000000001', 'infrastructure-monitoring-diagnostics', 1, 'Comprendo para qué sirve monitorear recursos como CPU, memoria, almacenamiento o disponibilidad.'),
('00000000-0000-0000-0000-000000000001', 'infrastructure-monitoring-diagnostics', 2, 'Puedo consultar métricas y registros sencillos para identificar el estado de un sistema.'),
('00000000-0000-0000-0000-000000000001', 'infrastructure-monitoring-diagnostics', 3, 'Tengo experiencia utilizando herramientas de monitoreo, interpretando métricas y registros e identificando problemas habituales de rendimiento o disponibilidad.'),
('00000000-0000-0000-0000-000000000001', 'infrastructure-monitoring-diagnostics', 4, 'Tengo experiencia configurando monitoreo y alertas, investigando incidentes y proponiendo mejoras para prevenir o resolver problemas de infraestructura.');
