-- NextRole V2 assessment persistence. Additive only; V1-V4 and the V1 roles catalog are intentionally unchanged.
CREATE TABLE assessment_roles (
    id VARCHAR(100) PRIMARY KEY,
    name VARCHAR(180) NOT NULL UNIQUE
);

CREATE TABLE assessment_questionnaire_versions (
    id UUID PRIMARY KEY,
    version_code VARCHAR(32) NOT NULL UNIQUE,
    published_at TIMESTAMPTZ NOT NULL,
    is_current BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE UNIQUE INDEX uq_assessment_questionnaire_current
    ON assessment_questionnaire_versions(is_current) WHERE is_current = TRUE;

CREATE TABLE assessment_questions (
    questionnaire_version_id UUID NOT NULL REFERENCES assessment_questionnaire_versions(id),
    competency_code VARCHAR(100) NOT NULL,
    position SMALLINT NOT NULL CHECK (position BETWEEN 1 AND 31),
    title VARCHAR(180) NOT NULL,
    question_text TEXT NOT NULL,
    PRIMARY KEY (questionnaire_version_id, competency_code),
    UNIQUE (questionnaire_version_id, position)
);

CREATE TABLE assessment_answer_options (
    questionnaire_version_id UUID NOT NULL,
    competency_code VARCHAR(100) NOT NULL,
    level SMALLINT NOT NULL CHECK (level BETWEEN 0 AND 4),
    description TEXT NOT NULL,
    PRIMARY KEY (questionnaire_version_id, competency_code, level),
    FOREIGN KEY (questionnaire_version_id, competency_code)
        REFERENCES assessment_questions(questionnaire_version_id, competency_code)
);

CREATE TABLE assessment_matrix_versions (
    id UUID PRIMARY KEY,
    version_code VARCHAR(32) NOT NULL UNIQUE,
    published_at TIMESTAMPTZ NOT NULL,
    is_current BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE UNIQUE INDEX uq_assessment_matrix_current
    ON assessment_matrix_versions(is_current) WHERE is_current = TRUE;

CREATE TABLE assessment_role_requirements (
    matrix_version_id UUID NOT NULL REFERENCES assessment_matrix_versions(id),
    role_id VARCHAR(100) NOT NULL REFERENCES assessment_roles(id),
    competency_code VARCHAR(100) NOT NULL,
    importance VARCHAR(24) NOT NULL CHECK (importance IN ('ESSENTIAL', 'COMPLEMENTARY', 'NOT_RELEVANT')),
    expected_level SMALLINT,
    PRIMARY KEY (matrix_version_id, role_id, competency_code),
    CHECK (
        (importance = 'NOT_RELEVANT' AND expected_level IS NULL)
        OR (importance IN ('ESSENTIAL', 'COMPLEMENTARY') AND expected_level BETWEEN 1 AND 4)
    )
);

CREATE TABLE assessment_attempts (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id),
    status VARCHAR(16) NOT NULL CHECK (status IN ('DRAFT', 'COMPLETED', 'DISCARDED')),
    questionnaire_version_id UUID NOT NULL REFERENCES assessment_questionnaire_versions(id),
    matrix_version_id UUID NOT NULL REFERENCES assessment_matrix_versions(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ,
    discarded_at TIMESTAMPTZ,
    source_attempt_id UUID REFERENCES assessment_attempts(id),
    UNIQUE (id, questionnaire_version_id),
    CHECK (
        (status = 'DRAFT' AND completed_at IS NULL AND discarded_at IS NULL)
        OR (status = 'COMPLETED' AND completed_at IS NOT NULL AND discarded_at IS NULL)
        OR (status = 'DISCARDED' AND completed_at IS NULL AND discarded_at IS NOT NULL)
    )
);
CREATE UNIQUE INDEX uq_assessment_attempt_one_active_draft_per_user
    ON assessment_attempts(user_id) WHERE status = 'DRAFT';
CREATE INDEX ix_assessment_attempt_user_completed
    ON assessment_attempts(user_id, completed_at DESC) WHERE status = 'COMPLETED';

CREATE TABLE assessment_answers (
    attempt_id UUID NOT NULL,
    questionnaire_version_id UUID NOT NULL,
    competency_code VARCHAR(100) NOT NULL,
    level SMALLINT NOT NULL CHECK (level BETWEEN 0 AND 4),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (attempt_id, competency_code),
    FOREIGN KEY (attempt_id, questionnaire_version_id)
        REFERENCES assessment_attempts(id, questionnaire_version_id),
    FOREIGN KEY (questionnaire_version_id, competency_code)
        REFERENCES assessment_questions(questionnaire_version_id, competency_code)
);

CREATE TABLE assessment_result_sets (
    attempt_id UUID PRIMARY KEY REFERENCES assessment_attempts(id),
    algorithm_version VARCHAR(50) NOT NULL,
    calculated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE assessment_role_results (
    result_set_id UUID NOT NULL REFERENCES assessment_result_sets(attempt_id),
    role_id VARCHAR(100) NOT NULL REFERENCES assessment_roles(id),
    score_numerator NUMERIC NOT NULL CHECK (score_numerator >= 0),
    score_denominator NUMERIC NOT NULL CHECK (score_denominator > 0),
    display_percentage NUMERIC(4,1) NOT NULL CHECK (display_percentage BETWEEN 0 AND 100),
    rank_position SMALLINT NOT NULL CHECK (rank_position BETWEEN 1 AND 6),
    PRIMARY KEY (result_set_id, role_id),
    UNIQUE (result_set_id, rank_position)
);

